<?php
namespace App\Models;use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\BelongsToMany;
final class CoverageDefinition extends Model{use HasUuids;protected$fillable=['insurance_line_id','code','name','description','limit_type','mandatory','status'];protected function casts():array{return['name'=>'array','description'=>'array','mandatory'=>'boolean'];}public function line():BelongsTo{return$this->belongsTo(InsuranceLine::class,'insurance_line_id');}public function products():BelongsToMany{return$this->belongsToMany(InsuranceProduct::class,'product_coverages')->withPivot(['default_limit_minor','default_deductible_minor','configuration','is_optional','display_order','inclusion','waiting_period_days','territory','coverage_period']);}}
